export type GraphicsQualityPreset = 'fast' | 'balanced' | 'high';

const GRAPHICS_QUALITY_STORAGE_KEY = 'pk_tcg_graphics_quality_v1';

export function loadSavedGraphicsQuality(): GraphicsQualityPreset {
  try {
    if (typeof window === 'undefined' || !window.localStorage) return 'balanced';
    const raw = window.localStorage.getItem(GRAPHICS_QUALITY_STORAGE_KEY);
    if (raw === 'fast' || raw === 'balanced' || raw === 'high') return raw;
  } catch {
    // Ignore storage access errors
  }
  return 'balanced';
}

export function saveGraphicsQuality(preset: GraphicsQualityPreset): void {
  try {
    if (typeof window !== 'undefined' && window.localStorage) {
      window.localStorage.setItem(GRAPHICS_QUALITY_STORAGE_KEY, preset);
    }
  } catch {
    // Ignore storage access errors
  }
}
