const characterFaceTexCache = new Map<string, THREE.Texture>();

export function createCharacterFaceTexture(
  expression: string = 'neutral',
  skinHex: string = '#ffe4cf'
): THREE.Texture {
  const cacheKey = `${expression}|${skinHex}`;
  const cached = characterFaceTexCache.get(cacheKey);
  if (cached) return cached;

  const canvas = document.createElement('canvas');
  canvas.width = 128;
  canvas.height = 128;
  const ctx = canvas.getContext('2d')!;

  // Skin background
  ctx.fillStyle = skinHex;
  ctx.fillRect(0, 0, 128, 128);

  // Soft rosy cheeks
  ctx.fillStyle = 'rgba(255, 120, 120, 0.28)';
  ctx.beginPath();
  ctx.arc(32, 74, 12, 0, Math.PI * 2);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(96, 74, 12, 0, Math.PI * 2);
  ctx.fill();

  // Eyebrows
  ctx.strokeStyle = '#27272a';
  ctx.lineWidth = 3;
  ctx.lineCap = 'round';
  ctx.beginPath();
  if (expression === 'happy' || expression === 'excited') {
    ctx.arc(40, 48, 10, Math.PI * 1.1, Math.PI * 1.9);
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(88, 48, 10, Math.PI * 1.1, Math.PI * 1.9);
    ctx.stroke();
  } else if (expression === 'surprised') {
    ctx.arc(40, 42, 10, Math.PI * 1.1, Math.PI * 1.9);
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(88, 42, 10, Math.PI * 1.1, Math.PI * 1.9);
    ctx.stroke();
  } else {
    ctx.moveTo(32, 48);
    ctx.lineTo(48, 48);
    ctx.moveTo(80, 48);
    ctx.lineTo(96, 48);
    ctx.stroke();
  }

  // Eyes
  ctx.fillStyle = '#18181b';
  if (expression === 'happy') {
    ctx.strokeStyle = '#18181b';
    ctx.lineWidth = 4;
    ctx.beginPath();
    ctx.arc(40, 60, 8, Math.PI * 1.1, Math.PI * 1.9);
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(88, 60, 8, Math.PI * 1.1, Math.PI * 1.9);
    ctx.stroke();
  } else if (expression === 'excited' || expression === 'surprised') {
    ctx.beginPath();
    ctx.arc(40, 60, 8, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.arc(88, 60, 8, 0, Math.PI * 2);
    ctx.fill();
    // Eye shine
    ctx.fillStyle = '#ffffff';
    ctx.beginPath();
    ctx.arc(42, 58, 2.5, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.arc(90, 58, 2.5, 0, Math.PI * 2);
    ctx.fill();
  } else {
    ctx.beginPath();
    ctx.arc(40, 60, 6.5, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.arc(88, 60, 6.5, 0, Math.PI * 2);
    ctx.fill();
    // Eye shine
    ctx.fillStyle = '#ffffff';
    ctx.beginPath();
    ctx.arc(42, 58, 2, 0, Math.PI * 2);
    ctx.fill();
    ctx.beginPath();
    ctx.arc(90, 58, 2.5, 0, Math.PI * 2);
    ctx.fill();
  }

  // Mouth
  ctx.strokeStyle = '#991b1b';
  ctx.lineWidth = 3.5;
  ctx.beginPath();
  if (expression === 'happy' || expression === 'excited' || expression === 'female_cashier') {
    ctx.arc(64, 82, 14, 0.15 * Math.PI, 0.85 * Math.PI);
    ctx.stroke();
  } else if (expression === 'surprised') {
    ctx.fillStyle = '#7f1d1d';
    ctx.beginPath();
    ctx.ellipse(64, 88, 7, 10, 0, 0, Math.PI * 2);
    ctx.fill();
    ctx.stroke();
  } else {
    ctx.moveTo(54, 86);
    ctx.lineTo(74, 86);
    ctx.stroke();
  }

  const texture = new THREE.CanvasTexture(canvas);
  texture.generateMipmaps = true;
  characterFaceTexCache.set(cacheKey, texture);
  return texture;
}

export function createCharacterHeadMesh(
  skinMat: THREE.Material,
  faceTex: THREE.Texture,
  width: number = 0.20,
  height: number = 0.22,
  depth: number = 0.19
): THREE.Mesh {
  const faceMat = new THREE.MeshStandardMaterial({
    map: faceTex,
    roughness: 0.6,
  });
  // Box materials order: [+X, -X, +Y, -Y, +Z, -Z]
  const materials = [skinMat, skinMat, skinMat, skinMat, faceMat, skinMat];
  const geo = new THREE.BoxGeometry(width, height, depth);
  return new THREE.Mesh(geo, materials);
}

export function createRadialLightPoolTexture(): THREE.Texture {
  const canvas = document.createElement('canvas');
  canvas.width = 256;
  canvas.height = 256;
  const ctx = canvas.getContext('2d')!;
  const grad = ctx.createRadialGradient(128, 128, 0, 128, 128, 128);
  grad.addColorStop(0, 'rgba(255, 238, 185, 0.75)');     // Bright warm incandescent core
  grad.addColorStop(0.24, 'rgba(253, 210, 75, 0.48)');   // Rich warm sodium-amber pool
  grad.addColorStop(0.52, 'rgba(245, 158, 11, 0.20)');   // Outer amber falloff
  grad.addColorStop(0.78, 'rgba(180, 83, 9, 0.06)');     // Faint warm edge
  grad.addColorStop(1.0, 'rgba(0, 0, 0, 0)');            // Smooth dropoff to darkness
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, 256, 256);
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

