function getNearestNavNode(x: number, y: number, z: number): string {
  let bestKey = y >= 2.6 ? 'op_promenade_south' : 'greeting';
  let bestDist = Infinity;
  for (const [key, node] of Object.entries(STORE_NAV_GRAPH)) {
    const ny = node.y ?? 0;
    const d = Math.hypot(node.x - x, node.z - z) + Math.abs(ny - y) * 3.0;
    if (d < bestDist) {
      bestDist = d;
      bestKey = key;
    }
  }
  return bestKey;
}

function findNavPath(
  startX: number,
  startY: number,
  startZ: number,
  goalX: number,
  goalY: number,
  goalZ: number
): StoreNavPoint[] {
  const startKey = getNearestNavNode(startX, startY, startZ);
  const goalKey = getNearestNavNode(goalX, goalY, goalZ);

  if (startKey === goalKey) {
    return [{ x: goalX, y: goalY, z: goalZ }];
  }

  const queue: string[] = [startKey];
  const cameFrom: Record<string, string | null> = { [startKey]: null };

  while (queue.length > 0) {
    const current = queue.shift()!;
    if (current === goalKey) break;

    const neighbors = STORE_NAV_GRAPH[current]?.links || [];
    for (const next of neighbors) {
      if (!(next in cameFrom)) {
        cameFrom[next] = current;
        queue.push(next);
      }
    }
  }

  if (!(goalKey in cameFrom)) {
    return [{ x: goalX, y: goalY, z: goalZ }];
  }

  const pathKeys: string[] = [];
  let curr: string | null = goalKey;
  while (curr !== null) {
    pathKeys.unshift(curr);
    curr = cameFrom[curr];
  }

  const path: StoreNavPoint[] = [];
  for (let i = 1; i < pathKeys.length; i++) {
    const n = STORE_NAV_GRAPH[pathKeys[i]];
    if (n) path.push({ x: n.x, y: n.y ?? 0, z: n.z });
  }

  const last = path[path.length - 1];
  if (!last || Math.hypot(last.x - goalX, last.z - goalZ) > 0.15 || Math.abs((last.y ?? 0) - goalY) > 0.2) {
    path.push({ x: goalX, y: goalY, z: goalZ });
  }

  return path;
}

