function buildHandheldScannerMesh(scale = 1): { group: THREE.Group; nozzle: THREE.Object3D } {
  const scannerGunGroup = new THREE.Group();
  const gunHandle = new THREE.Mesh(
    new THREE.BoxGeometry(0.042 * scale, 0.125 * scale, 0.046 * scale),
    new THREE.MeshStandardMaterial({ color: 0x1e293b, roughness: 0.45 })
  );
  gunHandle.position.set(0, -0.03 * scale, 0);
  gunHandle.rotation.x = -0.18;
  scannerGunGroup.add(gunHandle);

  const gunHead = new THREE.Mesh(
    new THREE.BoxGeometry(0.068 * scale, 0.062 * scale, 0.135 * scale),
    new THREE.MeshStandardMaterial({ color: 0x0284c7, metalness: 0.35, roughness: 0.32 })
  );
  gunHead.position.set(0, 0.045 * scale, 0.032 * scale);
  scannerGunGroup.add(gunHead);

  const gunTrigger = new THREE.Mesh(
    new THREE.BoxGeometry(0.018 * scale, 0.035 * scale, 0.025 * scale),
    new THREE.MeshStandardMaterial({ color: 0xf43f5e, roughness: 0.35 })
  );
  gunTrigger.position.set(0, 0.005 * scale, 0.026 * scale);
  scannerGunGroup.add(gunTrigger);

  const nozzle = new THREE.Object3D();
  nozzle.position.set(0, 0.045 * scale, 0.102 * scale);
  scannerGunGroup.add(nozzle);

  return { group: scannerGunGroup, nozzle };
}

