  private lastReportedFrontId: string | null = null;
  private lastReportedQueueCount: number = -1;

  // Collision Boxes
  private colliders: ShopBoxCollider[] = [];

  // Customer NPCs & Checkout Queue Line
  private customerGroup: THREE.Group = new THREE.Group();
  public customerQueueIds: string[] = [];
  public onCustomerDeparted?: (customerId: string) => void;
  public onCustomerQueueUpdated?: (firstCustomerId: string | null, queueCount: number) => void;
  private activeCustomers: Array<{
    mesh: THREE.Group;
    data: ShopCustomer;
    stateTimer: number;
  }> = [];

  // Procedural animated fans & neon signs
  private ceilingFans: THREE.Group[] = [];
