    officeGroup.add(chairGroup);

    // 7B. SEATED OFFICE STAFF NPC (Visible when hired and during 07:00-22:00 shift)
    const officeNpc = new THREE.Group();
    officeNpc.userData.noMerge = true;
    officeNpc.position.set(-10.82, 0, -15.82);
    officeNpc.rotation.y = 0.32;
    officeNpc.visible = this.isOfficeStaffHired && this.isStaffOnShift();

    const offSkinMat = new THREE.MeshStandardMaterial({ color: 0xffe0c4, roughness: 0.65 });
    const offShirtMat = new THREE.MeshStandardMaterial({ color: 0xe0f2fe, roughness: 0.45 });
    const offSleeveMat = new THREE.MeshStandardMaterial({ color: 0xbae6fd, roughness: 0.5 });
