    const offPantsMat = new THREE.MeshStandardMaterial({ color: 0x1e293b, roughness: 0.75 });
    const offShoeMat = new THREE.MeshStandardMaterial({ color: 0x111827, roughness: 0.45 });
    const offHairMat = new THREE.MeshStandardMaterial({ color: 0x5c3a21, roughness: 0.65 });

    const offHips = new THREE.Group();
    offHips.position.set(0, 0.62, 0);
    officeNpc.add(offHips);

    // Seated legs (thighs forward onto chair, shins down to floor)
    [-0.10, 0.10].forEach((lx) => {
      const thigh = new THREE.Mesh(new THREE.BoxGeometry(0.13, 0.13, 0.36), offPantsMat);
      thigh.position.set(lx, -0.02, 0.16);
      offHips.add(thigh);
      const shin = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.45, 0.13), offPantsMat);
      shin.position.set(lx, -0.28, 0.30);
      offHips.add(shin);
      const shoe = new THREE.Mesh(new THREE.BoxGeometry(0.13, 0.08, 0.21), offShoeMat);
      shoe.position.set(lx, -0.53, 0.34);
      offHips.add(shoe);
    });

    // Crisp light-blue dress shirt torso + tie + gold staff ID badge
    const offChest = new THREE.Mesh(new THREE.BoxGeometry(0.42, 0.48, 0.24), offShirtMat);
    offChest.position.set(0, 0.28, 0);
    offHips.add(offChest);

    const offTie = new THREE.Mesh(new THREE.BoxGeometry(0.055, 0.30, 0.025), offTieMat);
    offTie.position.set(0, 0.29, 0.125);
    offHips.add(offTie);

    const offBadge = new THREE.Mesh(new THREE.BoxGeometry(0.08, 0.06, 0.02), offBadgeMat);
    offBadge.position.set(0.12, 0.35, 0.126);
    offHips.add(offBadge);

    // Head + glasses + neat hair
    const offHeadGroup = new THREE.Group();
    offHeadGroup.position.set(0, 0.68, 0.02);
    offHips.add(offHeadGroup);

    const offFaceTex = createCharacterFaceTexture('happy', '#ffe0c4');
    const offHeadMesh = createCharacterHeadMesh(offSkinMat, offFaceTex, 0.22, 0.24, 0.21);
    offHeadGroup.add(offHeadMesh);

    const offHairTop = new THREE.Mesh(new THREE.BoxGeometry(0.24, 0.06, 0.235), offHairMat);
    offHairTop.position.set(0, 0.12, -0.005);
    offHeadGroup.add(offHairTop);

    const offHairBack = new THREE.Mesh(new THREE.BoxGeometry(0.24, 0.15, 0.045), offHairMat);
    offHairBack.position.set(0, 0.02, -0.105);
    offHeadGroup.add(offHairBack);

    const offGlasses = new THREE.Mesh(
      new THREE.BoxGeometry(0.19, 0.048, 0.025),
      new THREE.MeshStandardMaterial({ color: 0x38bdf8, roughness: 0.1, metalness: 0.75 })
    );
    offGlasses.position.set(0, 0.02, 0.115);
    offHeadGroup.add(offGlasses);

    // Arms reaching forward to type on the keyboard
    const offLeftArm = new THREE.Group();
    offLeftArm.position.set(-0.25, 0.46, 0.02);
    const offLArmMesh = new THREE.Mesh(new THREE.BoxGeometry(0.11, 0.38, 0.11), offSleeveMat);
    offLArmMesh.position.set(0, -0.17, 0.06);
    offLeftArm.add(offLArmMesh);
    offLeftArm.rotation.x = -0.92;
