          ceilingLamp.position.set(sx, wy + 1.05, 6.85);
          l3Group.add(ceilingLamp);

          // Cozy Interior Sofa & Glowing TV / Lamp inside apartment room
          const sofa = new THREE.Mesh(new THREE.BoxGeometry(1.45, 0.56, 0.58), aptSofaMat);
          sofa.position.set(sx - 0.72, wy - 0.80, 6.38);
