    // Rooftop Sky-Garden Parapet, Cedar Pergola, Accent Glow & Potted Shrubs (shifted +17.0m for 12-story tower)
    const roofParapetGlass = new THREE.Mesh(new THREE.BoxGeometry(31.8, 0.82, 0.08), aptBalconyGlassMat);
    roofParapetGlass.position.set(0, 21.42 + floorHeightDelta, 7.75);
    l3Group.add(roofParapetGlass);

    const roofHandrail = new THREE.Mesh(new THREE.BoxGeometry(32.0, 0.08, 0.12), aptBronzeMat);
