    // Sorting Conveyor Table right inside Bay 02
    const sortTable = new THREE.Mesh(new THREE.BoxGeometry(2.6, 0.85, 1.05), hubRackSteelMat);
    sortTable.position.set(0, 0.46, -4.2);
