    // Parked Truck 1: Backed directly into BAY 01 open shutter with rear cargo door open & hazard lights blinking
    const hubTruckA = buildRonExpressBoxTruck({ rearDoorOpen: true });
    hubTruckA.group.position.set(-9.5, 0.04, -9.8);
    hubTruckA.group.rotation.y = Math.PI / 2; // Nose faces -Z street, open rear cargo faces +Z Bay 01
    hubTruckA.brakeMat.emissiveIntensity = 1.4;
    depotGroup.add(hubTruckA.group);
