    counterGroup.add(trophyGroup);

    // 3J. Physical Items Placed on Counter (Staging Mat -> Laser Scanner -> Bagging Zone)
    this.counterItemsGroup = new THREE.Group();
    this.counterItemsGroup.userData.noMerge = true;
    counterGroup.add(this.counterItemsGroup);

    // G. HIRED CASHIER NPC (Clean blocky-voxel uniform matching Office Staff style)
    // Standing inside counter booth: X = -3.20, Y = 0, Z = 3.92 facing forward toward POS & customer (+Z)
    this.cashierNpcGroup = new THREE.Group();
