    // 3. Head + Happy Face + Neat Hair + Cyan Glasses (Exact Office Staff style)
    const cHeadGroup = new THREE.Group();
    cHeadGroup.position.set(0, 0.68, 0.02);
    cashierHips.add(cHeadGroup);

    const faceTex = createCharacterFaceTexture('happy', '#ffe0c4');
    const cHeadMesh = createCharacterHeadMesh(cashierSkinMat, faceTex, 0.22, 0.24, 0.21);
