    // 4. Left & Right Blocky Arms + Hands + Handheld Barcode Scanner
    const lArmGroup = new THREE.Group();
    lArmGroup.position.set(-0.26, 0.46, 0.02);
    const lArmMesh = new THREE.Mesh(new THREE.BoxGeometry(0.11, 0.36, 0.11), cashierSleeveMat);
    lArmMesh.position.set(0, -0.16, 0.04);
