    const lHandMesh = new THREE.Mesh(new THREE.BoxGeometry(0.095, 0.09, 0.095), cashierSkinMat);
    lHandMesh.position.set(0, -0.36, 0.04);
    lArmGroup.add(lHandMesh);
    lArmGroup.rotation.x = -0.58;
    cashierHips.add(lArmGroup);

    const rArmGroup = new THREE.Group();
    rArmGroup.position.set(0.26, 0.46, 0.02);
    const rArmMesh = new THREE.Mesh(new THREE.BoxGeometry(0.11, 0.36, 0.11), cashierSleeveMat);
    rArmMesh.position.set(0, -0.16, 0.04);
