  // WALL CARD DISPLAY SHELVING (REDUCED TO EXACTLY 3 DISTINCT SHELVES)
  // Matching user request: "giảm bớt kệ chưng bày card lại còn 3 kệ thôi và cơ chế kệ cũng tương tự như bàn đứng vàng"
  // Each shelf has 2 tiers x 3 slots = 6 real card stands with yellow retail price tags (18 slots total)
  // ==========================================
  private buildWallCardDisplayShelves() {
    const wallShelvesGroup = new THREE.Group();

    const shelfFrameMat = new THREE.MeshStandardMaterial({
      color: 0x181c24,
      metalness: 0.8,
      roughness: 0.25,
    });
    const shelfBackMat = new THREE.MeshStandardMaterial({
      color: 0x0f1115,
      metalness: 0.4,
      roughness: 0.5,
    });
    const shelfLipMat = new THREE.MeshStandardMaterial({
      color: 0xcbd5e1,
      metalness: 0.9,
      roughness: 0.15,
    });
    const goldTrimMat = new THREE.MeshStandardMaterial({
      color: 0xd4af37,
      metalness: 0.95,
      roughness: 0.2,
      emissive: 0x785608,
      emissiveIntensity: 0.2,
    });

    // EXACTLY 3 SHELVES CENTERED ON BACK WALL
    // Shelf 0: X = -5.5 (Fire & Dragon Legends)
    // Shelf 1: X =  0.0 (30th Anniversary Vintage)
    // Shelf 2: X = +5.5 (Secret Illustration Rares)
    const shelfConfigs = [
      {
        x: -5.5,
        title: '🔥 KỆ #1: FIRE & DRAGON LEGENDS',
        accentColor: '#ea580c',
        neonHex: 0xf97316,
      },
      {
        x: 0.0,
        title: '⚡ KỆ #2: 30TH ANNIVERSARY GRAILS',
        accentColor: '#eab308',
        neonHex: 0xfacc15,
      },
      {
        x: 5.5,
        title: '✨ KỆ #3: SECRET ILLUSTRATION RARES',
        accentColor: '#a855f7',
        neonHex: 0xc084fc,
      },
    ];

    this.shelfStandMeshes = [];
    this.cardShelfLockGroups = [];

    shelfConfigs.forEach((cfg, shelfIdx) => {
      const shelfUnit = new THREE.Group();
      shelfUnit.position.set(cfg.x, 0, -11.15);

      const shelfW = 2.6;
      const shelfH = 2.4;
      const shelfD = 0.35;

      // 1. Bottom Kickplate Base Cabinet (Y = 0.18m)
      const baseMesh = new THREE.Mesh(new THREE.BoxGeometry(shelfW + 0.1, 0.36, shelfD + 0.08), shelfFrameMat);
      baseMesh.position.set(0, 0.18, 0);
      shelfUnit.add(baseMesh);

      // Gold Trim Base Accent
      const baseTrim = new THREE.Mesh(new THREE.BoxGeometry(shelfW + 0.12, 0.04, shelfD + 0.1), goldTrimMat);
      baseTrim.position.set(0, 0.37, 0);
      shelfUnit.add(baseTrim);

      // 2. Dark Textured Backboard
      const backBoard = new THREE.Mesh(new THREE.BoxGeometry(shelfW, shelfH, 0.04), shelfBackMat);
      backBoard.position.set(0, shelfH / 2 + 0.15, -shelfD / 2 + 0.02);
      shelfUnit.add(backBoard);

      // 3. Left & Right Upright Frame Columns
      const leftCol = new THREE.Mesh(new THREE.BoxGeometry(0.08, shelfH + 0.2, shelfD), shelfFrameMat);
      leftCol.position.set(-shelfW / 2 - 0.04, shelfH / 2 + 0.15, 0);
      shelfUnit.add(leftCol);

      const rightCol = new THREE.Mesh(new THREE.BoxGeometry(0.08, shelfH + 0.2, shelfD), shelfFrameMat);
      rightCol.position.set(shelfW / 2 + 0.04, shelfH / 2 + 0.15, 0);
      shelfUnit.add(rightCol);

      // 4. Overhead Illuminated Canopy Marquee (Y = 2.55m)
      const canopy = new THREE.Mesh(new THREE.BoxGeometry(shelfW + 0.2, 0.26, shelfD + 0.12), shelfFrameMat);
      canopy.position.set(0, shelfH + 0.28, 0);
      shelfUnit.add(canopy);

      // Canopy Glowing Header Signboard
      const signCanvas = document.createElement('canvas');
      signCanvas.width = 512;
      signCanvas.height = 96;
      const sCtx = signCanvas.getContext('2d')!;
      sCtx.fillStyle = '#090b0e';
      sCtx.fillRect(0, 0, signCanvas.width, signCanvas.height);
      sCtx.strokeStyle = cfg.accentColor;
      sCtx.lineWidth = 6;
      sCtx.strokeRect(3, 3, signCanvas.width - 6, signCanvas.height - 6);
      sCtx.fillStyle = '#ffffff';
      sCtx.font = '900 24px "Arial Black", sans-serif';
      sCtx.textAlign = 'center';
      sCtx.textBaseline = 'middle';
      sCtx.fillText(cfg.title, signCanvas.width / 2, signCanvas.height / 2);
      const signTex = new THREE.CanvasTexture(signCanvas);
      signTex.colorSpace = THREE.SRGBColorSpace;

      const headerSign = new THREE.Mesh(
        new THREE.PlaneGeometry(shelfW - 0.1, 0.20),
        new THREE.MeshStandardMaterial({
          map: signTex,
          emissive: cfg.neonHex,
          emissiveIntensity: 0.45,
        })
      );
      headerSign.position.set(0, shelfH + 0.28, shelfD / 2 + 0.07);
      shelfUnit.add(headerSign);

      // 5. 2 DISPLAY TIERS (Lower Y = 0.82m, Upper Y = 1.48m)
      const tierYs = [0.82, 1.48];
      const slotXOffsets = [-0.74, 0, 0.74];

      tierYs.forEach((tierY, tierIdx) => {
        // Horizontal Silver Shelf Lip Bar
        const shelfPlank = new THREE.Mesh(new THREE.BoxGeometry(shelfW - 0.04, 0.04, shelfD - 0.04), shelfLipMat);
        shelfPlank.position.set(0, tierY, 0);
        shelfUnit.add(shelfPlank);

        // Gold Trim on Front Shelf Edge
        const plankTrim = new THREE.Mesh(new THREE.BoxGeometry(shelfW - 0.02, 0.02, 0.02), goldTrimMat);
        plankTrim.position.set(0, tierY, shelfD / 2 - 0.02);
        shelfUnit.add(plankTrim);

        // 3 Real Card Display Stands per tier (Total 6 cards per shelf)
        slotXOffsets.forEach((slotX, colIdx) => {
          const slotGroup = new THREE.Group();
          slotGroup.position.set(slotX, tierY + 0.02, 0.02);

          // Card Stand Base
          const standBase = new THREE.Mesh(new THREE.BoxGeometry(0.24, 0.02, 0.12), goldTrimMat);
          standBase.position.set(0, 0.01, 0);
          slotGroup.add(standBase);

          // Card Mesh with high-res artwork, slightly tilted backward
          const cardGroup = new THREE.Group();
          cardGroup.position.set(0, 0.26, -0.01);
          cardGroup.rotation.x = -0.09;

          const cardMesh = new THREE.Mesh(
            new THREE.PlaneGeometry(0.32, 0.46),
            new THREE.MeshStandardMaterial({
              map: createShowcaseCardTexture(undefined),
              roughness: 0.9,
              metalness: 0.0,
              side: THREE.FrontSide,
            })
          );
          cardMesh.userData.noMerge = true;
          cardMesh.position.z = 0.005;
          cardGroup.add(cardMesh);

          // Solid dark backing plate
          const backPlate = new THREE.Mesh(
            new THREE.PlaneGeometry(0.32, 0.46),
            new THREE.MeshStandardMaterial({
              color: 0x111318,
              roughness: 0.8,
              metalness: 0.1,
              side: THREE.FrontSide,
            })
          );
          backPlate.position.z = -0.001;
          backPlate.rotation.y = Math.PI;
          cardGroup.add(backPlate);

          slotGroup.add(cardGroup);

          // Real Yellow Retail Price Tag Sticker on Shelf Edge
          const tagMesh = new THREE.Mesh(
            new THREE.PlaneGeometry(0.22, 0.08),
            new THREE.MeshStandardMaterial({
              map: createShowcasePriceTagTexture(0, false),
              side: THREE.DoubleSide,
            })
          );
          tagMesh.userData.noMerge = true;
          tagMesh.position.set(0, 0.03, shelfD / 2 - 0.05);
          tagMesh.rotation.x = -0.32;
          slotGroup.add(tagMesh);

          shelfUnit.add(slotGroup);

          const slotIndex = tierIdx * 3 + colIdx;
          this.shelfStandMeshes.push({
            shelfIndex: shelfIdx,
            slotIndex,
            cardMesh,
            tagMesh,
          });
        });
      });

      const shelfUnlockDef = SHELF_UNLOCKS.find((s) => s.id === `shelf_card_${shelfIdx + 1}`);
      if (shelfUnlockDef) {
        const lockOverlay = this.createShelfLockOverlay(shelfW - 0.04, 2.02, shelfUnlockDef);
        lockOverlay.userData.noMerge = true;
        lockOverlay.position.set(0, 1.38, shelfD / 2 + 0.04);
        lockOverlay.visible = !isShelfUnlocked(this.unlockedShelves, shelfUnlockDef.id);
        shelfUnit.add(lockOverlay);
        this.cardShelfLockGroups.push(lockOverlay);
      }

      wallShelvesGroup.add(shelfUnit);
    });

    this.mergeStaticGroupMeshes(wallShelvesGroup);
    this.shopInteriorRoot.add(wallShelvesGroup);
  }

