  private buildColliderBuckets() {
    this.colliderBuckets.clear();
    const bucketWidth = 16;
    for (let i = 0; i < this.colliders.length; i++) {
      const c = this.colliders[i];
      const bMin = Math.floor(c.minX / bucketWidth);
      const bMax = Math.floor(c.maxX / bucketWidth);
      for (let b = bMin; b <= bMax; b++) {
        let list = this.colliderBuckets.get(b);
        if (!list) {
          list = [];
          this.colliderBuckets.set(b, list);
        }
        list.push(c);
      }
    }
  }

  // ==========================================
  // CUSTOMER NPC SPAWNER & UPDATE
  // ==========================================
  public syncCustomers(customers: ShopCustomer[]) {
    // Reconcile 3D customer meshes with customers array
    const activeIds = new Set(customers.map((c) => c.id));
    this.activeCustomers = this.activeCustomers.filter((item) => {
      if (!activeIds.has(item.data.id)) {
        item.mesh.userData?.glbHandle?.dispose?.();
        this.customerGroup.remove(item.mesh);
        // Also remove from queue if present
        const qIdx = this.customerQueueIds.indexOf(item.data.id);
        if (qIdx !== -1) {
          this.customerQueueIds.splice(qIdx, 1);
        }
        return false;
      }
      return true;
    });

    // Add new meshes or sync external state transitions safely without clobbering active 3D AI status
    customers.forEach((cust) => {
      const existing = this.activeCustomers.find((a) => a.data.id === cust.id);
      if (!existing) {
        const mesh = this.createCustomerMesh(cust);
        this.customerGroup.add(mesh);
        this.activeCustomers.push({ mesh, data: { ...cust, basket: [...(cust.basket || [])] }, stateTimer: 0 });
      } else {
        // Preserve authoritative 3D scene status once customer has entered unless React explicitly triggers leaving (e.g. checkout)
        if (cust.status === 'leaving' && existing.data.status !== 'leaving') {
          existing.data.status = 'leaving';
          existing.data.speechBubble = cust.speechBubble;
          existing.mesh.userData.subState = 'leaving';
          existing.mesh.userData.exitStep = 0;
          existing.mesh.userData.navPath = null;
          existing.mesh.userData.navIndex = 0;
          const hasBought = Boolean(existing.data.basket && existing.data.basket.length > 0);
          if (existing.mesh.userData.bagGroup) {
            existing.mesh.userData.bagGroup.visible = false;
          }
          if (existing.mesh.userData.retailBagGroup) {
            existing.mesh.userData.retailBagGroup.visible = hasBought;
          }
          const qIdx = this.customerQueueIds.indexOf(cust.id);
          if (qIdx !== -1) {
            this.customerQueueIds.splice(qIdx, 1);
          }
        }
        // Only adopt React basket if it has more items than local (never drop scene-picked items)
        if (cust.basket && cust.basket.length > (existing.data.basket?.length || 0)) {
          existing.data.basket = [...cust.basket];
          existing.data.budget = cust.budget;
        }
      }
    });

    // Notify queue status ONLY if front customer is at register and has items in basket
    let readyFrontId: string | null = null;
    if (this.customerQueueIds.length > 0) {
      const frontId = this.customerQueueIds[0];
      const frontCust = this.activeCustomers.find((c) => c.data.id === frontId);
      if (frontCust && frontCust.data.basket && frontCust.data.basket.length > 0) {
        const dist = Math.hypot(frontCust.mesh.position.x - (-3.15), frontCust.mesh.position.z - 6.0);
        if (dist < 0.45) {
          readyFrontId = frontId;
        }
      }
    }
    if (readyFrontId !== this.lastReportedFrontId || this.customerQueueIds.length !== this.lastReportedQueueCount) {
      this.lastReportedFrontId = readyFrontId;
      this.lastReportedQueueCount = this.customerQueueIds.length;
      this.onCustomerQueueUpdated?.(readyFrontId, this.customerQueueIds.length);
    }
  }

