      if (vis || shouldStepOffscreen) {
        this._accumDior += delta;
        if (vis ? (dSq <= 2500 || frame % 3 === 2) : frame % 12 === 8) {
          this.diorNpcController.update(this._accumDior, this.currentRawHour);
          this._accumDior = 0;
        }
      }
