          id: ftId,
          x: ft.group.position.x,
          y: -0.26,
          z: ft.group.position.z,
          moveDirX: ft.bdDir,
          moveDirZ: 0,
          halfW: 1.15,
          halfL: 2.95,
          lookahead: 13.0,
          minGap: 2.4,
          priority: 30,
