        const yaw = ft.group.rotation.y;
        const clr = this.trafficCoordinator.getForwardClearance({
          id: ftId,
          x: ft.group.position.x,
          y: -0.26,
          z: ft.group.position.z,
          moveDirX: Math.cos(yaw),
          moveDirZ: -Math.sin(yaw),
          halfW: 1.15,
          halfL: 2.95,
          lookahead: 8.5,
          minGap: 1.8,
          priority: 36,
        });
        const sf = Math.max(0.2, clr.maxSpeedFactor);
        if (sf < 0.75) isPausedOrBraking = true;
        ft.speed = 6.0 * sf;
        const prevX = ft.group.position.x;
        const prevZ = ft.group.position.z;
