        ft.group.position.y = this.getRonTruckGroundY(ft.group.position.z);
        const steerT = THREE.MathUtils.clamp((ft.group.position.z - 34.75) / 5.2, 0, 1);
        ft.group.rotation.y = THREE.MathUtils.lerp(Math.PI, Math.PI / 2, steerT);

