            id: ftId,
            x: ft.group.position.x,
            y: ft.group.position.y,
            z: ft.group.position.z,
            moveDirX: 0,
            moveDirZ: 1,
            halfW: 1.15,
            halfL: 2.95,
            lookahead: 8.0,
            minGap: 1.8,
            priority: 22,
