          const targetSpd = baseSpd * clr.maxSpeedFactor;
          ft.speed = THREE.MathUtils.lerp(
            ft.speed,
            targetSpd,
            Math.min(1, delta * (clr.maxSpeedFactor === 0 ? 6.5 : 4.0))
          );
          ft.group.position.z = Math.min(ft.garageZ, ft.group.position.z + ft.speed * delta);
          ft.group.position.y = this.getRonTruckGroundY(ft.group.position.z);

